parameters.functionScript:
/* TASK-L186 §5. The learner pressed "Ask your coach about this". Open the
   panel in its loading state and ask for the thread about THIS card. The
   anchor is the row's own kind and id, which the kit emitted with the press. */
Outputs.open = true;
Outputs.status = 'loading';
Outputs.turns = [];
Outputs.rejected = '';
Outputs.sending = false;
Outputs.anchorKind = String(Inputs.anchorKind || '');
Outputs.anchorId = String(Inputs.anchorId || '');
Outputs.call();

/* TASK-L186 §5. A coach pressed Reply on a message. Open the thread that
   message belongs to. A coach never names an anchor: they answer a thread the
   learner started (sprint 54 §2.1). */
Outputs.open = true;
Outputs.status = 'loading';
Outputs.turns = [];
Outputs.rejected = '';
Outputs.sending = false;
Outputs.conversationId = String(Inputs.conversationId || '');
Outputs.call();

/* TASK-L186 §5. The panel's Send. Who is reading decides which write — the
   same `audience` the kit row already threw on if it was anything else. The
   panel only emits a body that is non-empty and inside the limit; the server
   refuses again rather than trusting it. */
Outputs.sending = true;
Outputs.rejected = '';
Outputs.body = String(Inputs.body || '');
if (String(Inputs.audience || '') === 'coach') Outputs.callCoach();
else Outputs.callLearner();

/* The thread, as the server says THIS reader sees it (unread is theirs). */
Outputs.turns = Inputs.turns || [];
Outputs.status = 'ready';

/* The write landed. The panel clears its box only when `sent` changes, so the
   token is new every time — a second identical message must clear it too. */
Outputs.turns = Inputs.turns || [];
Outputs.status = 'ready';
Outputs.sending = false;
Outputs.rejected = '';
Outputs.sent = String(Date.now()) + Math.random().toString(16).slice(2);

/* The server's REASON, never its sentence (shared/Thread). The words stay in
   the box: losing somebody's question to a refusal would be the worst answer. */
const why = String(Inputs.error || '');
Outputs.sending = false;
Outputs.rejected = why === 'too_long' ? 'too_long' : why === 'notice-not-accepted' ? 'stale' : 'error';
